CREATE TABLE IF NOT EXISTS gis_inec_evidence_validation_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phase text NOT NULL, artifact_id uuid NOT NULL, artifact_sha256 text NOT NULL, parser_version text NOT NULL, candidate_count integer NOT NULL DEFAULT 0, confirmed_count integer NOT NULL DEFAULT 0, insufficient_count integer NOT NULL DEFAULT 0, conflict_count integer NOT NULL DEFAULT 0, not_found_count integer NOT NULL DEFAULT 0, unverified_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'RUNNING', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS gis_inec_evidence_validation_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), run_id uuid NOT NULL REFERENCES gis_inec_evidence_validation_runs(id), candidate_match_id uuid NOT NULL, artifact_id uuid NOT NULL, artifact_sha256 text NOT NULL, canonical_source_key text NOT NULL, source_registry_id uuid, parser_version text NOT NULL, evidence_decision text NOT NULL, evidence_reference jsonb NOT NULL DEFAULT '{}'::jsonb, validation_errors jsonb NOT NULL DEFAULT '[]'::jsonb, decision_fingerprint text NOT NULL, candidate_status_before text NOT NULL, candidate_mutation boolean NOT NULL DEFAULT false, validated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(run_id,candidate_match_id), UNIQUE(decision_fingerprint));
CREATE INDEX IF NOT EXISTS gis_inec_evidence_validation_candidate_idx ON gis_inec_evidence_validation_decisions(candidate_match_id,validated_at DESC);
CREATE INDEX IF NOT EXISTS gis_inec_evidence_validation_artifact_idx ON gis_inec_evidence_validation_decisions(artifact_id,artifact_sha256);